function makePart(label, subtitle, system, glyph, summary, location, next, source, url, status, position, hitSize, accent) {
  return {
    label: label,
    subtitle: subtitle,
    system: system,
    glyph: glyph,
    signal: "About this component",
    summary: summary,
    location: location,
    next: next,
    source: source,
    url: url,
    status: status,
    position: position,
    hitSize: hitSize,
    accent: accent
  };
}

